using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new Exception("Edit only");
            AssetDatabase.ImportAsset("Assets/Art/InvestigationV36/R102/WORKSHOP.fbx", ImportAssetOptions.ForceUpdate);
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/InvestigationV36/R102/WORKSHOP.fbx");
            var mesh = asset.GetComponentInChildren<MeshFilter>().sharedMesh;
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            foreach (string name in new[]{"WorkshopShell_SourceFBX", "ModelShell", "ClipShell"})
            {
                var t = s.GetComponentsInChildren<Transform>(true).Single(x => x.name == name);
                t.GetComponent<MeshFilter>().sharedMesh = mesh;
                foreach (var c in t.GetComponents<MeshCollider>())
                    c.sharedMesh = mesh;
            }

            var sc = s.gameObject.scene;
            EditorSceneManager.MarkSceneDirty(sc);
            EditorSceneManager.SaveScene(sc);
            sc = EditorSceneManager.OpenScene(sc.path);
            int missing = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).Sum(t => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
            string text = "r102 headroom FBX mesh=" + mesh.name + " bounds=" + mesh.bounds + " Missing=" + missing + " Interactables=" + Object.FindObjectsByType<InvestigationInteractable>(FindObjectsSortMode.None).Length;
            File.WriteAllText("Test/KetQua/investigation_r102/headroom-integration.txt", text);
            if (missing != 0)
                throw new Exception(text);
            r.Log(text);
        }
    }
}

